<template><section class="kfe-admin-section"><h2>LOAN STATUS</h2><div v-if="loanItems.length" class="kfe-admin-list"><article v-for="loan in loanItems" :key="loan.id||loan.loanId||loan.name" class="kfe-admin-card"><strong>{{loan.name||loan.lender||loan.loanNumber||'Loan'}}</strong><p>Remaining balance: {{money(loan.remainingBalancePaise??loan.remaining_balance_paise??loan.balancePaise)}}</p><p>EMI: {{money(loan.emiPaise??loan.emi_paise)}} · {{loan.status||'Active'}}</p></article></div><p v-else class="kfe-boundary-note">No authoritative loan status is currently available.</p></section></template>
<script setup>import {computed} from 'vue';const props=defineProps({loanModel:{default:null},money:{type:Function,required:true}});const loanItems=computed(()=>{const v=props.loanModel;return Array.isArray(v)?v:(v?.loans||v?.items||v?.records||[])})</script>
